from collections import deque
R,C=len(grid),len(grid[0]); seen=set(); q=deque()
for r in range(R):
 for c in range(C):
  if (r in (0,R-1) or c in (0,C-1)) and grid[r][c]==9: seen.add((r,c));q.append((r,c))
while q:
 r,c=q.popleft()
 for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
  p=(r+dr,c+dc)
  if 0<=p[0]<R and 0<=p[1]<C and grid[p[0]][p[1]]==9 and p not in seen: seen.add(p);q.append(p)
enclosed=[(r,c) for r in range(R) for c in range(C) if grid[r][c]==9 and (r,c) not in seen]
enclosed, len(enclosed)
